#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace DeliveryService.Mok.Editor {
public static class PrologueCameraUpgrade {
 public static void InspectDriving(){var d=UnityEngine.Object.FindFirstObjectByType<BankPrologue>();string s="";foreach(var f in d.getawayCar.GetComponentsInChildren<MeshFilter>(true))if(f.name.Contains("Steering"))s+=f.name+" pos="+d.getawayCar.InverseTransformPoint(f.transform.position)+" rot="+f.transform.localEulerAngles+" scale="+f.transform.lossyScale+" mesh="+f.sharedMesh.bounds+" world="+f.GetComponent<Renderer>().bounds+"\n";var rig=d.drive.GetComponent<PrologueDrivingHands>();if(rig){foreach(var t in new[]{rig.leftUpper,rig.leftLower,rig.leftHand,rig.leftGrip})s+=t.name+" "+d.getawayCar.InverseTransformPoint(t.position)+"\n";foreach(var t in rig.leftHand.GetComponentsInChildren<Transform>())s+=t.name+" local="+t.localPosition+"\n";}File.WriteAllText("Logs/Driving-rig-inspect.txt",s);}
 public static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(BankPrologueBuilder.ScenePath);if(!scene.isLoaded)scene=EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath,UnityEditor.SceneManagement.OpenSceneMode.Additive);if(!EditorSceneManager.SaveScene(scene,"Logs/Bank-before-camera-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new Exception("Backup failed");var d=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();var a=d.shopArrival;
 if(!a.conversationPlayer){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonCity/Prefabs/Characters/Character_Male_Hoodie.prefab"),a.shop);g.name="Player - shop conversation";g.transform.localPosition=new Vector3(4.8f,0,6.1f);g.transform.rotation=a.shop.rotation*Quaternion.Euler(0,180,0);var anim=g.GetComponentInChildren<Animator>();anim.runtimeAnimatorController=a.animator.runtimeAnimatorController;anim.applyRootMotion=false;anim.cullingMode=AnimatorCullingMode.AlwaysAnimate;foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);a.conversationPlayer=g.transform;}
 Transform Shot(string name,Vector3 position,Vector3 focus){var t=a.shop.Find(name);if(!t){t=new GameObject(name).transform;t.SetParent(a.shop,false);}t.localPosition=position;t.LookAt(a.shop.TransformPoint(focus));return t;}
 a.mingiShot=Shot("Mingi dialogue shot",new Vector3(4.5f,1.6f,5.65f),new Vector3(3.22f,1.35f,3.85f));a.playerShot=Shot("Player reply shot",new Vector3(2.55f,1.6f,4.1f),new Vector3(4.8f,1.35f,6.1f));
 d.drive.driverEye=new Vector3(-.38f,1.17f,.1f);d.drive.cockpitFov=80;EditorUtility.SetDirty(a);EditorUtility.SetDirty(d.drive);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 string report="Saved dialogue reverse shots and driver eye\n";foreach(var r in d.getawayCar.GetComponentsInChildren<Renderer>(true))report+=r.name+" : "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name:"null"))+"\n";File.WriteAllText("Logs/Prologue-camera-apply.txt",report);}
}}
#endif
